[[module CSS]]

@import url('https://fonts.googleapis.com/css2?family=Geologica:wght@100..900&display=swap');



:root {

    --medium-accent: 138, 33, 33;

    --accent-hex: #8a2121;

    --paper: #f3eed9;

    --shadow: 2px 2px 3px #5e5e5e82;

    --bar: #b6bdc7;

}



/* Info Container Color */

.info-container {

    --barColour: var(--accent-hex);

}



/* == TYPOGRAPHY == */

/* Primary titles */

.title,

.warningtitle {

    font-family: "Geologica", sans-serif;

    --wght: 700;

    font-size: 2em;

}



/* Secondary titles/subheads */

.sub {

    --wght: 600;

    font-size: 1.6em;

}



/* Base warning title color (details overridden in Warning section) */

.warningtitle {

    color: #80bb38;

}



/* == ADDENDUM == */

/* Gray container around addendum cards */

.addendumout {

    background: #ededed;

    border-top: 0.25em solid var(--accent-hex);

    border-bottom: 0.25em solid var(--accent-hex);

    width: 95%;

    padding: 0.3125em 0.9375em;

    margin: 1.25em auto;

    box-shadow: var(--shadow);

    text-align: center;

}



/* White inner card that holds content */

.addendumin {

    background: #fff;

    width: 90%;

    padding: 0.3125em 0.9375em;

    margin: 0.625em auto;

    text-align: left;

    box-shadow: 1px 1px 4px #5e5e5e82;

    color: #000;

}



/* == INTERVIEW == */

/* Standard interview block with border */

.interview {

    background: #fff;

    border: none;

    border-left: 0.3125em solid var(--accent-hex);

    width: 89%;

    padding: 0.3125em 0.9375em;

    margin: 1.25em auto;

    box-shadow: var(--shadow);

}



/* Green Aquino variant */

.aquino {

    border-left: 3px solid #2e5200;

}



/*  == STAMPS & SIGNATURE  == */

/* Circular logo stamp */

.stamp::after {

    content: "";

    position: absolute;

    right: 3.125em;

    bottom: 0.3125em;

    width: 7.5em;

    aspect-ratio: 1 / 1;

    display: block;

    background-image: url("https://scptestwiki.wdfiles.com/local--files/secret%3Athetrench-test/logo2.png");

    background-repeat: no-repeat;

    background-position: center;

    background-size: contain;

    transform: rotate(-30deg);

    transform-origin: center;

    z-index: 1;

    pointer-events: none;

}



/* Stamp rotation variations */

.stamp-one::after { transform: rotate(30deg); }

.stamp-two::after { transform: rotate(-25deg); }

.stamp-three::after { transform: rotate(50deg); }

.stamp-four::after { transform: rotate(-35deg); }

.stamp-five::after { transform: rotate(-70deg); }



/* Stamp positioning */

.addendumin.stamp { 

    position: relative; 

}



/* Right-aligned signature line */

.signature {

    display: block;

    margin-right: 9.6875em;

}





.addendumin.stamp::after{

  z-index:0 !important;

}



.addendumin .signature{

  display:block !important;

  float:none !important;

  clear:both !important;

  margin: .5em 10em 0 0;

  position:relative;

  z-index: 5;

}



/* == WARNING == */

/* Spin animation */

@keyframes spin { 

    100% { transform: rotate(360deg); } 

}



/* Black warning box with green border */

.warningmemo { 

    background: #1a1a1a; 

    background-size: contain; 

    background-position: top center; 

    background-repeat: no-repeat; 

    box-shadow: 0 0 0.3125em rgba(0, 0, 0, .5); 

    width: 90%; 

    margin: 0 auto 1.5em auto; 

    padding: 1em 1.25em 1.25em 1.25em; 

    word-break: break-word; 

    border-top: solid 0.33em #2c5100; 

    border-bottom: solid 0.33em #2c5100; 

    display: flex; 

    align-items: center; 

    flex-wrap: wrap; 

    box-sizing: border-box;

}



/* Logo inside warning band */

.logosection { 

    flex: 0 0 15.875em; 

    padding: 0 0.625em 0.625em 0; 

}



/* Warning logo spin */

.warning .logosection img { 

    z-index: 0; 

    animation: spin 20s cubic-bezier(1, 1, 1, 1) infinite; 

    filter: drop-shadow(0 0 0.1rem black); 

    display: block; 

    width: 100%; 

    height: auto; 

    margin: 0;

    margin-left: 1em; 

}



/* Warning titles flex */

.titlesection { 

    flex: 1 1 0; 

    min-width: 13.75em; 

}



/* Warning title */

.warningtitle { 

    font-family: "Geologica", sans-serif; 

    font-weight: 700; 

    font-size: clamp(1.375em, 5vw, 2.5em); 

    line-height: 1.1; 

    color: #80bb38; 

    display: block; 

}



/* Warning subtitle */

.totem { 

    font-size: clamp(1.125em, 4.2vw, 2.125em); 

}



/* Green earning header content box */

.warningin { 

    background: #2d5200; 

    width: auto; 

    padding: 0.625em 0.9375em; 

    margin: 0.75em 0 0 0; 

    text-align: left; 

    box-shadow: 0.0625em 0.0625em 0.25em #5e5e5e82; 

    color: white;

    flex: 1 1 100%; 

    box-sizing: border-box; 

}



/* == OVERVIEW & COMMENTS == */

/* Assessment Table */

.table {

    border-top: 3px solid #2e5200;

    border-bottom: 3px solid #2e5200;

    background: #d5dccc;

    width: 90%;

    padding: 0.2em 0.9375em;

    margin: .75em auto;

    box-shadow: var(--shadow);

}



/* D-class overview box */

.overview {

    background: #1a1a1a;

    width: 90%;

    padding: 0.3125em 0.9375em;

    margin: 0.625em auto;

    color: white;

    box-shadow: var(--shadow);

    text-align: left;

}



/* Indented overview comments */

.comment { 

    margin-left: 1.25em; 

}



.reply { 

    margin-left: 2.1875em; 

}



/* D-class color coding */

.twonine { 

    color: #e2f1ff; 

    font-weight: bold; 

}



.oneninetwo { 

    color: #ce9ca0; 

    font-weight: bold; 

}



/* Green list divider */

.list { 

    border-bottom: 3px solid #2e5200; 

}



/* == ETHICS COMMITTEE  == */

/* Ethics Committee blue box */

.ethicsone { 

    background:#3d4e65;

    border-top:5px solid #091e32;

    border-bottom:5px solid #091e32;

    color:#f1f1e6;

}



/* Ethics Committee text box */

.ethicstwo {

    background-color:#f1f1e6;

    border: none;

}



/* Ethics decorative bars */

.ethicshead {

    position: relative;

    padding: 12px 84px;

    overflow: visible;

    text-align: center;

    display: flex;

    justify-content: center;

    align-items: center;

}



/* Ethics title housekeeping */

.ethicshead .title {

    position: relative;

    z-index: 1;

}



/* Decorative bars */

.ethicshead::before,

.ethicshead::after {

    content:"";

    position:absolute;

    top:50%;

    transform:translateY(-50%);

    width:60px;

    height:90px;

    background-repeat:no-repeat;

    z-index:10;

}



/* Left Ethics bars */

.ethicshead::before{

  left:3px;

  background-image:

    linear-gradient(var(--bar),var(--bar)),

    linear-gradient(var(--bar),var(--bar)),

    linear-gradient(var(--bar),var(--bar));

  background-size:12px 88px,12px 77px,12px 66px;

  background-position:48px 100%, 24px 100%, 0 100%;

}



/* Right Ethics bars */

.ethicshead::after{

  right:3px;

  background-image:

    linear-gradient(var(--bar),var(--bar)),

    linear-gradient(var(--bar),var(--bar)),

    linear-gradient(var(--bar),var(--bar));

  background-size:12px 66px,12px 77px,12px 88px;

  background-position:48px 100%, 24px 100%, 0 100%;

}



/* == MOBILE PARITY == */

/* Warning Box */

@media (max-width: 30em) {

    .warningmemo { 

        display: grid; 

        grid-template-columns: 6em 1fr; 

        grid-auto-rows: auto; 

        align-items: center; 

    }



    .titlesection { min-width: 0; }

    .warningin { 

        grid-column: 1 / -1; 

        margin: 0.75em 0 0 0; 

        width: auto; 

    }

}



