/* Fire Diamond */



/* Diamond with quadrants */



.fire-diamond {

  position: relative;

  width: 140px;

  height: 140px;

  margin: 40px auto;

}



.fire-diamond .quad {

  position: absolute;

  width: 50px;

  height: 50px;

  transform-origin: center;

  display: flex;

  align-items: center;

  justify-content: center;

  border: 1px solid #000;

  box-sizing: border-box;

  box-shadow: 1px 1px 5px rgba(0,0,0,.5);

}



/* Position and rotate each quadrant with spacing */

.fire-diamond .top {

  top: 0;

  left: 45px;

  transform: rotate(45deg);

}

.fire-diamond .left {

  top: 45px;

  left: 0;

  transform: rotate(-45deg);

}

.fire-diamond .right {

  top: 45px;

  left: 90px;

  transform: rotate(135deg);

}

.fire-diamond .bottom {

  top: 90px;

  left: 45px;

  transform: rotate(-135deg);

}



/* Icon inside each quadrant */

.fire-diamond .icon {

  width: 36px;

  height: 36px;

  background-size: contain;

  background-repeat: no-repeat;

  background-position: center;

}



.fire-diamond .top .icon    { transform: rotate(-45deg);}

.fire-diamond .left .icon   { transform: rotate(45deg);}

.fire-diamond .right .icon  { transform: rotate(-135deg);}

.fire-diamond .bottom .icon { transform: rotate(135deg);}



