----



[[include <a href="http://scp-wiki.wikidot.com/component:image-features-source">:scp-wiki:component:image-features-source</a> |hover-enlarge=--]

|enlarge-amount=10

|speed=15

|float=true

|align=right

|width=300px 

|url=http://scp-sandbox-3.wdfiles.com/local--files/balthazaar-contest-drafts/Cafeitfob

